<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();ensure_donations_schema();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='settings'){
  $s=db()->prepare('INSERT INTO settings(`key`,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)');
  foreach(['donation_minimum_clp'=>(string)max(0,(int)$_POST['minimum']),'donation_required'=>isset($_POST['required'])?'1':'0','donation_intro'=>trim((string)$_POST['intro']),'donation_frequency'=>in_array($_POST['frequency']??'monthly',['monthly','once'],true)?$_POST['frequency']:'monthly'] as $k=>$v)$s->execute([$k,$v]);
  flash('success','Configuración de aportes actualizada.');redirect('../admin/donations.php');
 }
 if($action==='save_method'){
  $id=(int)($_POST['id']??0);$type=in_array($_POST['method_type']??'',['bank','crypto','payment'],true)?$_POST['method_type']:'bank';$title=trim((string)$_POST['title']);if($title==='')throw new RuntimeException('El título del método es obligatorio.');
  $values=[$type,$title,trim((string)$_POST['description']),trim((string)$_POST['bank_name']),trim((string)$_POST['account_holder']),trim((string)$_POST['rut']),trim((string)$_POST['account_type']),trim((string)$_POST['account_number']),trim((string)$_POST['email']),trim((string)$_POST['wallet_address']),trim((string)$_POST['network']),isset($_POST['active'])?1:0,(int)$_POST['sort_order']];
  if($id){$values[]=$id;db()->prepare('UPDATE donation_methods SET method_type=?,title=?,description=?,bank_name=?,account_holder=?,rut=?,account_type=?,account_number=?,email=?,wallet_address=?,network=?,active=?,sort_order=?,updated_at=NOW() WHERE id=?')->execute($values);}else{db()->prepare('INSERT INTO donation_methods(method_type,title,description,bank_name,account_holder,rut,account_type,account_number,email,wallet_address,network,active,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($values);}
  flash('success','Método de aporte guardado.');redirect('../admin/donations.php');
 }
 if($action==='delete_method'){$id=(int)$_POST['id'];db()->prepare('DELETE FROM donation_methods WHERE id=?')->execute([$id]);flash('success','Método eliminado. Los aportes históricos conservarán sus datos generales.');redirect('../admin/donations.php');}
 if($action==='review'){$id=(int)$_POST['id'];$status=in_array($_POST['status']??'',['verified','rejected','pending'],true)?$_POST['status']:'pending';db()->prepare('UPDATE donations SET status=?,admin_note=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$status,trim((string)$_POST['admin_note']),(int)user()['id'],$id]);flash('success','Aporte revisado.');redirect('../admin/donations.php?view='.$id);}
}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM donation_methods WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$methods=db()->query('SELECT * FROM donation_methods ORDER BY sort_order,title')->fetchAll();
$donations=db()->query('SELECT d.*,u.username,p.display_name,m.title method_title,m.method_type FROM donations d JOIN users u ON u.id=d.seller_id LEFT JOIN profiles p ON p.user_id=u.id LEFT JOIN donation_methods m ON m.id=d.method_id ORDER BY d.created_at DESC LIMIT 200')->fetchAll();
$view=null;if(isset($_GET['view'])){$q=db()->prepare('SELECT d.*,u.username,u.email,p.display_name,p.business_local,m.* FROM donations d JOIN users u ON u.id=d.seller_id LEFT JOIN profiles p ON p.user_id=u.id LEFT JOIN donation_methods m ON m.id=d.method_id WHERE d.id=?');$q->execute([(int)$_GET['view']]);$view=$q->fetch();}
$summary=db()->query("SELECT COALESCE(SUM(CASE WHEN status='verified' THEN amount_clp ELSE 0 END),0) verified,COUNT(*) total,SUM(status='pending') pending FROM donations")->fetch();
$adminPage='donations';$adminTitle='Donaciones y sostenimiento';$adminSubtitle='Datos bancarios, cripto, servicios de pago y comprobantes de vendedores';require __DIR__.'/partials/header.php';
?>
<div class="admin-grid cols-3"><div class="stat-card"><span>💰</span><div><small>Verificado</small><b><?=money_clp((int)$summary['verified'])?></b></div></div><div class="stat-card"><span>⏳</span><div><small>Pendientes</small><b><?=number_format((int)$summary['pending'])?></b></div></div><div class="stat-card"><span>🎯</span><div><small>Meta por vendedor</small><b><?=money_clp(donation_minimum())?></b></div></div></div>
<div class="admin-grid-2"><section class="admin-card"><h2>⚙️ Aportes voluntarios</h2><form method="post" class="admin-form-stack"><?=csrf_field()?><input type="hidden" name="action" value="settings"><div class="form-grid"><label>Monto sugerido CLP<input type="number" min="0" step="1000" name="minimum" value="<?=donation_minimum()?>"></label><label>Frecuencia<select name="frequency"><option value="monthly" <?=setting('donation_frequency','monthly')==='monthly'?'selected':''?>>Mensual</option><option value="once" <?=setting('donation_frequency')==='once'?'selected':''?>>Una sola vez</option></select></label></div><label class="check-card"><input type="checkbox" name="required" <?=donation_required()?'checked':''?>> Destacar este aporte como meta voluntaria de sostenimiento</label><label>Mensaje para vendedores<textarea name="intro" rows="5"><?=e(setting('donation_intro','Tu aporte ayuda a mantener, mejorar y administrar la plataforma. Envía el comprobante para que el equipo pueda verificarlo.'))?></textarea></label><button class="admin-btn primary">Guardar política</button></form></section>
<section class="admin-card"><h2><?=$edit?'✏️ Editar método':'➕ Nuevo método de aporte'?></h2><form method="post" class="admin-form-stack"><?=csrf_field()?><input type="hidden" name="action" value="save_method"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="form-grid"><label>Tipo<select name="method_type"><option value="bank" <?=($edit['method_type']??'')==='bank'?'selected':''?>>Banco chileno</option><option value="crypto" <?=($edit['method_type']??'')==='crypto'?'selected':''?>>Criptomoneda</option><option value="payment" <?=($edit['method_type']??'')==='payment'?'selected':''?>>Servicio de pago</option></select></label><label>Título<input name="title" required placeholder="BancoEstado, Binance, World App, PayPal..." value="<?=e($edit['title']??'')?>"></label></div><label>Descripción detallada<textarea name="description" rows="4"><?=e($edit['description']??'')?></textarea></label><div class="form-grid"><label>Nombre de banco<input name="bank_name" value="<?=e($edit['bank_name']??'')?>"></label><label>Nombre y apellido<input name="account_holder" value="<?=e($edit['account_holder']??'')?>"></label><label>RUT<input name="rut" placeholder="12.345.678-9" value="<?=e($edit['rut']??'')?>"></label><label>Tipo de cuenta<input name="account_type" placeholder="Cuenta RUT / Corriente" value="<?=e($edit['account_type']??'')?>"></label><label>Número de cuenta<input name="account_number" value="<?=e($edit['account_number']??'')?>"></label><label>Correo<input type="email" name="email" value="<?=e($edit['email']??'')?>"></label><label>Wallet / identificador<input name="wallet_address" value="<?=e($edit['wallet_address']??'')?>"></label><label>Red / moneda<input name="network" placeholder="USDT TRC20, PayPal USD..." value="<?=e($edit['network']??'')?>"></label><label>Orden<input type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label></div><label class="check-card"><input type="checkbox" name="active" <?=!isset($edit['active'])||$edit['active']?'checked':''?>> Método visible para vendedores</label><button class="admin-btn primary">Guardar método</button></form></section></div>
<section class="admin-card"><div class="panel-head"><div><h2>🏦 Métodos publicados</h2><p>Los datos sensibles solo se muestran a vendedores autenticados.</p></div></div><div class="template-library"><?php foreach($methods as $m):?><article class="template-card <?=$m['active']?'active':''?>"><div class="template-card-body"><div><h3><?=e($m['title'])?></h3><span class="admin-badge"><?=e($m['method_type'])?></span></div><p><?=e(mb_strimwidth((string)$m['description'],0,150,'…'))?></p><small><?=e($m['bank_name']?:$m['network']?:'Sin detalle adicional')?></small></div><div class="template-card-actions"><a class="admin-btn small" href="?edit=<?=$m['id']?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este método?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_method"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="admin-btn small danger">Eliminar</button></form></div></article><?php endforeach;?><?php if(!$methods):?><p>No hay métodos configurados. Agrega un banco, Binance, World App, PayPal u otro servicio.</p><?php endif;?></div></section>
<section class="admin-card"><div class="panel-head"><div><h2>🧾 Comprobantes recibidos</h2><p>Revisa y valida cada aporte antes de contabilizarlo.</p></div><input class="admin-search" data-filter-table="#donationTable" placeholder="Buscar vendedor o referencia..."></div><div class="admin-table-wrap"><table class="admin-table" id="donationTable"><thead><tr><th>Vendedor</th><th>Método</th><th>Monto</th><th>Fecha</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($donations as $d):?><tr><td><b><?=e($d['display_name']?:$d['username'])?></b><small>@<?=e($d['username'])?></small></td><td><?=e($d['method_title']?:'Método eliminado')?><small><?=e($d['reference_code']?:'Sin referencia')?></small></td><td><b><?=money_clp((int)$d['amount_clp'])?></b><?php if($d['external_amount']):?><small><?=e((string)$d['external_amount'].' '.$d['external_currency'])?></small><?php endif;?></td><td><?=e(date('d/m/Y H:i',strtotime($d['donated_at'])))?></td><td><span class="status <?=e($d['status'])?>"><?=e($d['status'])?></span></td><td><a class="admin-btn small" href="?view=<?=$d['id']?>">Revisar</a></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($view):?><section class="admin-card review-card"><div class="panel-head"><div><h2>🔎 Aporte #<?=$view['id']?></h2><p><?=e($view['display_name']?:$view['username'])?> · <?=e($view['business_local']?:'Sin local')?></p></div><a class="admin-btn" href="donations.php">Cerrar</a></div><div class="admin-grid-2"><div><div class="donation-detail"><b><?=money_clp((int)$view['amount_clp'])?></b><span><?=e($view['title']?:'Método eliminado')?> · <?=e(date('d/m/Y H:i',strtotime($view['donated_at'])))?></span><p><?=nl2br(e($view['seller_message']))?></p><code><?=e($view['reference_code']?:'Sin código de referencia')?></code><?php if($view['proof_file']):?><p><a class="admin-btn" target="_blank" href="<?=url($view['proof_file'])?>">📎 Abrir comprobante</a></p><?php endif;?></div></div><form method="post" class="admin-form-stack"><?=csrf_field()?><input type="hidden" name="action" value="review"><input type="hidden" name="id" value="<?=$view['id']?>"><label>Estado<select name="status"><option value="pending">Pendiente</option><option value="verified" <?=$view['status']==='verified'?'selected':''?>>Verificado</option><option value="rejected" <?=$view['status']==='rejected'?'selected':''?>>Rechazado</option></select></label><label>Nota administrativa<textarea name="admin_note" rows="6"><?=e($view['admin_note'])?></textarea></label><button class="admin-btn success">Guardar revisión</button></form></div></section><?php endif;?>
<?php require __DIR__.'/partials/footer.php';?>
